/* Dark theme removed: the app is light-only. Kept as a no-op so any page that
   still loads it (or calls toggleDarkMode) does nothing; clears the old choice. */
(function(){try{localStorage.removeItem('dm');localStorage.removeItem('employee_theme');}catch(e){}
document.documentElement.classList.remove('dark-mode');
document.addEventListener('DOMContentLoaded',function(){document.body.classList.remove('dark-mode');});
window.toggleDarkMode=function(){};})();
